'use client';

import { useEffect, useLayoutEffect, useRef } from 'react';
import './chat-typing-relay.css';

export interface ChatMessage {
  id: number;
  from: string;
  text: string;
  mine?: boolean;
}

export interface ChatTypingRelayProps {
  messages: ChatMessage[];
  /** Who is typing right now, if anyone. */
  typing: string | null;
  label: string;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * A chat transcript: a typing indicator bubbles in, is replaced by the
 * message, and the next speaker's indicator follows. The transcript is a
 * plain ordered list, so it reads well without the animation.
 */
export function ChatTypingRelay({
  messages,
  typing,
  label,
  className = '',
}: ChatTypingRelayProps) {
  const list = useRef<HTMLOListElement>(null);
  useIsomorphicLayoutEffect(() => {
    const el = list.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages.length, typing]);

  return (
    <div className={`mg-chat ${className}`}>
      <ol ref={list} className='mg-chat__list' aria-label={label} tabIndex={0}>
        {messages.map((m) => (
          <li key={m.id} className='mg-chat__msg' data-mine={Boolean(m.mine)}>
            <span className='mg-chat__from'>{m.from}</span>
            <span className='mg-chat__bubble'>{m.text}</span>
          </li>
        ))}
        {typing ? (
          <li
            className='mg-chat__msg mg-chat__msg--typing'
            aria-label={`${typing} is typing`}
          >
            <span className='mg-chat__from'>{typing}</span>
            <span className='mg-chat__bubble' aria-hidden='true'>
              <i />
              <i />
              <i />
            </span>
          </li>
        ) : null}
      </ol>
      <p className='mg-chat__sr' aria-live='polite'>
        {typing
          ? `${typing} is typing`
          : messages.length
            ? `${messages[messages.length - 1].from}: ${messages[messages.length - 1].text}`
            : ''}
      </p>
    </div>
  );
}

.mg-chat {
  color: var(--mg-ink, #0c1738);
}

.mg-chat__list {
  display: grid;
  gap: 8px;
  align-content: start;
  height: 230px;
  margin: 0;
  padding: 12px;
  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 14px;
  background: var(--mg-foam, #f5f8ff);
  list-style: none;
  scroll-behavior: smooth;
}

.mg-chat__list:focus-visible {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-chat__msg {
  display: grid;
  gap: 2px;
  justify-items: start;
  animation: mg-chat-in 260ms cubic-bezier(0.3, 1.3, 0.5, 1);
}

.mg-chat__msg[data-mine='true'] {
  justify-items: end;
}

.mg-chat__from {
  color: #6b7699;
  font-size: 11px;
  font-weight: 600;
}

.mg-chat__bubble {
  max-width: 80%;
  padding: 8px 12px;
  border-radius: 14px 14px 14px 4px;
  background: #fff;
  box-shadow: 0 1px 2px rgba(12, 23, 56, 0.12);
}

.mg-chat__msg[data-mine='true'] .mg-chat__bubble {
  border-radius: 14px 14px 4px 14px;
  background: var(--mg-accent, #164cff);
  color: #fff;
}

.mg-chat__msg--typing .mg-chat__bubble {
  display: flex;
  gap: 4px;
  padding: 12px 14px;
}

.mg-chat__msg--typing i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #8a96bd;
  animation: mg-chat-dot 1s ease-in-out infinite;
}

.mg-chat__msg--typing i:nth-child(2) {
  animation-delay: 0.15s;
}

.mg-chat__msg--typing i:nth-child(3) {
  animation-delay: 0.3s;
}

.mg-chat__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  overflow: hidden;
  clip-path: inset(50%);
}

@keyframes mg-chat-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.96);
  }
}

@keyframes mg-chat-dot {
  0%,
  60%,
  100% {
    transform: none;
    opacity: 0.5;
  }
  30% {
    transform: translateY(-4px);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-chat__list {
    scroll-behavior: auto;
  }
  .mg-chat__msg,
  .mg-chat__msg--typing i {
    animation: none;
  }
}
